mapper.select:
select u.user_id, u.app_id, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark, d.dept_name, d.leader from vpn_user u left join vpn_dept d on u.dept_id = d.dept_id where u.del_flag = '0'
AND u.app_id = #{appId}
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM vpn_dept t WHERE find_in_set(#{deptId}, ancestors) ))

select user_id, user_name from vpn_user where user_name = #{userName} and del_flag = '0'

	and app_id = #{appId}

limit 1

mapper.update:
update vpn_user
app_id = #{appId}, dept_id = #{deptId}, user_name = #{userName}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, encrypted_pwd = #{encryptedPwd}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, pwd_update_date = #{pwdUpdateDate}, update_by = #{updateBy}, remark = #{remark}, yianlian_id = #{yianlianId}, update_time = sysdate()
where user_id = #{userId}
